    pub(crate) fn compare_buffer_properties(
        &self,
        _other: &Document,
        a: &BufferProperties,
        b: &BufferProperties,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_header_length() != b.get_header_length() {
            return Err(format!("{path}: HEADER_LENGTH mismatch"));
        }
        if a.get_in_place() != b.get_in_place() {
            return Err(format!("{path}: IN_PLACE mismatch"));
        }
        Ok(())
    }

